mapper.update:
UPDATE customer_service_session
SET status = #{status}, update_time = NOW()
WHERE session_id = #{sessionId}

mapper.select:
SELECT s.id, s.session_id, s.user_id, u.nickname as userName, u.username as userAccount, s.customer_service_id, cs.nickname as customerServiceName, s.status, s.start_time, s.end_time, s.last_message_time, (SELECT content FROM customer_service_message WHERE session_id = s.session_id ORDER BY create_time DESC LIMIT 1) as lastMessageContent, s.create_time, s.update_time FROM customer_service_session s LEFT JOIN sys_user u ON s.user_id = u.id LEFT JOIN sys_user cs ON s.customer_service_id = cs.id WHERE 1=1
AND s.status = #{status}
ORDER BY s.last_message_time DESC
